interface IRoute {
    // Note, only extend enums at the end to maintain backward compatibility.
    enum Domain {
        ETHEREUM,
        AVALANCHE,
        OP_MAINNET,
        ARBITRUM_ONE,
        BASE,
        POLYGON_MAINNET,
        ETHEREUM_SEPOLIA,
        AVALANCHE_FUJI,
        OP_SEPOLIA,
        ARBITRUM_SEPOLIA,
        BASE_SEPOLIA,
        POLYGON_AMOY,
        UNICHAIN,
        BSC,
        LINEA,
        GNOSIS_CHAIN,
        WORLD_CHAIN,
        INK,
        HYPER_EVM,
        TEMPO,
        STABLE,
        TRON
    }

    enum Provider {
        LOCAL,
        CCTP,
        ACROSS,
        STARGATE,
        EVERCLEAR_DEPRECATED,
        SUPERCHAIN_STANDARD_BRIDGE,
        ARBITRUM_GATEWAY,
        GNOSIS_OMNIBRIDGE,
        USDT0,
        CCTP_V2,
        POLYGON_POS_BRIDGE
    }

    enum PoolType {
        ASSETS,
        ALL
    }

    error ZeroAddress();
    error ProcessFailed();
    error UnsupportedDomain();
    error InvalidLength();
}
